const url = ($input.first().json.body.website || '').toLowerCase().trim();

if (!url) {
  return [{ json: { website_status: 'NO_WEBSITE', is_call_prospect: true } }];
}

// Check directory and social domain patterns
const socialAndDirectoryDomains = [
  'facebook.com', 'fb.com', 'instagram.com', 'zomato.com',
  'swiggy.com', 'justdial.com', 'google.com', 'maps.google.com',
  'indiamart.com', 'tradeindia.com', 'yellowpages.com'
];

const isSocialOrDirectory = socialAndDirectoryDomains.some(domain => url.includes(domain));

if (isSocialOrDirectory) {
  return [{ json: { website_status: 'NO_WEBSITE', directory_link: url, is_call_prospect: true } }];
} else {
  return [{ json: { website_status: 'HAS_WEBSITE', primary_domain: url, is_call_prospect: false } }];
}
